import { useEffect, useRef, useState, type FormEvent, type ReactNode } from 'react';
import {
  LayoutDashboard, Briefcase, Users, ListChecks, CalendarDays, Settings,
  Search, Plus, ArrowRight, ArrowLeft, X, FileText, Sparkles, Upload,
  Download, Copy, RefreshCw, AlertCircle, CheckCircle2, Clock3,
  ShieldCheck, LogOut, Link2, Pencil, Trash2, Check,
} from 'lucide-react';
import type { AppConfig, Workspace, Job, Candidate, Application, Analysis, AnalysisMode, Criterion, Stage, Interview, Evidence } from '../shared/types';
import { stageLabels, statusLabels } from '../shared/types';

type Page = 'dashboard' | 'jobs' | 'candidates' | 'tasks' | 'interviews' | 'settings';
type JobDraft = Pick<Job, 'title' | 'department' | 'location' | 'employmentType' | 'description' | 'status' | 'criteria'>;
type RunAction = (key: string, work: () => Promise<unknown>, success?: string) => Promise<boolean>;
const navigation: { id: Page; label: string; icon: typeof Users }[] = [
  { id: 'dashboard', label: '工作台', icon: LayoutDashboard },
  { id: 'jobs', label: '岗位画像', icon: Briefcase },
  { id: 'candidates', label: '候选人', icon: Users },
  { id: 'tasks', label: '匹配任务', icon: ListChecks },
  { id: 'interviews', label: '面试管理', icon: CalendarDays },
  { id: 'settings', label: '工作区设置', icon: Settings },
];
const jobStatus = { open: '招聘中', paused: '已暂停', closed: '已关闭' };
const taskStatus = { queued: '排队中', running: '分析中', succeeded: '已完成', failed: '失败' };
const outcomeLabels = { pending: '待面试', pass: '通过', hold: '待定', reject: '不通过' };
const formatDate = (value: string, withTime = false) => new Intl.DateTimeFormat('zh-CN', { month: '2-digit', day: '2-digit', ...(withTime ? { hour: '2-digit', minute: '2-digit' } : {}) }).format(new Date(value));
const modeLabel = (mode: AnalysisMode) => mode === 'llm' ? 'AI 模型分析' : '规则辅助';
const initials = (name: string) => name.slice(0, 2);
function errorText(error: unknown) { return error instanceof Error ? error.message : '请求未完成，请重试。'; }
async function api<T>(path: string, options: RequestInit = {}): Promise<T> {
  const res = await fetch(path, { credentials: 'same-origin', ...options, headers: { ...(options.body && !(options.body instanceof FormData) ? { 'Content-Type': 'application/json' } : {}), ...options.headers } });
  const value = await res.json().catch(() => ({ error: '服务器返回了无法识别的响应，请检查服务日志。' }));
  if (!res.ok) throw new Error(value.error || `请求失败（${res.status}）`);
  return value as T;
}
const json = (method: string, value?: unknown): RequestInit => ({ method, ...(value === undefined ? {} : { body: JSON.stringify(value) }) });
function latestAnalysis(workspace: Workspace, applicationId: string) { return workspace.analyses.filter(a => a.applicationId === applicationId).sort((a, b) => b.createdAt.localeCompare(a.createdAt))[0]; }
function Badge({ children, tone = 'neutral' }: { children: ReactNode; tone?: string }) { return <span className={`badge ${tone}`}>{children}</span>; }
function Empty({ title, description, action }: { title: string; description?: string; action?: ReactNode }) { return <div className="empty"><div className="empty-icon"><FileText size={25} /></div><h3>{title}</h3>{description && <p>{description}</p>}{action}</div>; }
function InlineError({ message }: { message: string | null }) { return message ? <div className="inline-error" role="alert"><AlertCircle size={17} /><span>{message}</span></div> : null; }
function SectionHeading({ title, description, actions }: { title: string; description?: string; actions?: ReactNode }) { return <div className="section-heading"><div><h1>{title}</h1>{description && <p>{description}</p>}</div>{actions && <div className="heading-actions">{actions}</div>}</div>; }
function Modal({ title, subtitle, children, onClose, wide = false }: { title: string; subtitle?: string; children: ReactNode; onClose: () => void; wide?: boolean }) {
  const ref = useRef<HTMLDivElement>(null);
  const onCloseRef = useRef(onClose);
  onCloseRef.current = onClose;
  useEffect(() => {
    const before = document.activeElement as HTMLElement | null;
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    ref.current?.querySelector<HTMLElement>('input, select, textarea, button')?.focus();
    const handler = (event: KeyboardEvent) => {
      if (event.key === 'Escape') onCloseRef.current();
      if (event.key !== 'Tab') return;
      const controls = ref.current?.querySelectorAll<HTMLElement>('button:not(:disabled), input:not(:disabled), select:not(:disabled), textarea:not(:disabled), a[href]');
      if (!controls?.length) return;
      const first = controls[0]; const last = controls[controls.length - 1];
      if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
      if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
    };
    document.addEventListener('keydown', handler);
    return () => { document.removeEventListener('keydown', handler); document.body.style.overflow = previousOverflow; before?.focus(); };
  }, []);
  return <div className="modal-backdrop" onMouseDown={event => { if (event.target === event.currentTarget) onClose(); }}><div ref={ref} className={`modal ${wide ? 'wide' : ''}`} role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header><div><h2 id="dialog-title">{title}</h2>{subtitle && <p>{subtitle}</p>}</div><button className="icon-button" aria-label="关闭对话框" onClick={onClose}><X size={21} /></button></header>{children}</div></div>;
}

export default function App() {
  const [page, setPage] = useState<Page>(() => { const value = location.hash.slice(1); return navigation.some(item => item.id === value) ? value as Page : 'dashboard'; });
  const [workspace, setWorkspace] = useState<Workspace | null>(null);
  const [config, setConfig] = useState<AppConfig | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const [busy, setBusy] = useState('');
  const [jobId, setJobId] = useState<string | null>(null);
  const [candidateId, setCandidateId] = useState<string | null>(null);
  const [jobModal, setJobModal] = useState<{ job?: Job; copy?: boolean } | null>(null);
  const [candidateModal, setCandidateModal] = useState<{ candidate?: Candidate } | null>(null);
  const [linkModal, setLinkModal] = useState<{ jobId?: string; candidateId?: string } | null>(null);
  const [interviewModal, setInterviewModal] = useState<{ applicationId?: string; interview?: Interview } | null>(null);
  async function refresh() { const next = await api<Workspace>('/api/workspace'); setWorkspace(next); setConfig(next.config); }
  async function initialize() {
    setLoading(true); setError(null);
    try { const initial = await api<AppConfig>('/api/config'); setConfig(initial); if (!initial.authRequired || initial.authenticated) await refresh(); }
    catch (err) { setError(errorText(err)); }
    finally { setLoading(false); }
  }
  useEffect(() => { void initialize(); }, []);
  const hasActiveTasks = workspace?.tasks.some(task => task.status === 'queued' || task.status === 'running') ?? false;
  useEffect(() => {
    if (!hasActiveTasks) return;
    const timer = window.setInterval(() => { void refresh().catch(err => setError(errorText(err))); }, 2000);
    return () => clearInterval(timer);
  }, [hasActiveTasks]);
  useEffect(() => {
    if (!notice) return;
    const timer = window.setTimeout(() => setNotice(null), 6000);
    return () => clearTimeout(timer);
  }, [notice]);
  async function run(key: string, work: () => Promise<unknown>, success?: string) {
    setBusy(key); setError(null);
    try { await work(); await refresh(); if (success) setNotice(success); return true; }
    catch (err) { setError(errorText(err)); return false; }
    finally { setBusy(''); }
  }
  function navigate(next: Page) { setPage(next); setJobId(null); setCandidateId(null); location.hash = next; setError(null); }
  function openCandidate(id: string) { setCandidateId(id); setJobId(null); setPage('candidates'); location.hash = 'candidates'; }
  function openJob(id: string) { setJobId(id); setCandidateId(null); setPage('jobs'); location.hash = 'jobs'; }
  if (loading) return <div className="boot"><Brand /><div className="spinner" /><p>正在打开招聘工作台…</p></div>;
  if (config?.authRequired && !config.authenticated) return <Login onLogin={initialize} />;
  if (!workspace) return <div className="boot"><Brand /><InlineError message={error || '未能连接工作区。'} /><button className="button primary" onClick={() => void initialize()}><RefreshCw size={16} />重新连接</button><p>请确认 API 服务已启动，并与网页使用同一地址。</p></div>;
  const selectedCandidate = workspace.candidates.find(candidate => candidate.id === candidateId);
  const selectedJob = workspace.jobs.find(job => job.id === jobId);
  const pending = workspace.applications.filter(application => application.stage === 'review').length;
  return <div className="app-shell">
    <aside className="sidebar"><Brand /><div className="workspace-switch"><span className="workspace-monogram">Y</span><div><strong>我的招聘工作区</strong><span>小团队 · 本地优先</span></div><span className="workspace-dot" /></div><div className="nav-caption">招聘管理</div><nav aria-label="主导航">{navigation.map(item => <button key={item.id} className={`nav-item ${page === item.id ? 'active' : ''}`} onClick={() => navigate(item.id)}><item.icon size={19} /><span>{item.label}</span>{item.id === 'candidates' && pending > 0 && <span className="nav-counter">{pending}</span>}</button>)}</nav><div className="sidebar-bottom"><div className="sidebar-note"><ShieldCheck size={20} /><strong>以证据支持判断</strong><p>保留原文与评价版本，让每一次招聘决策有据可查。</p></div><div className="sidebar-user"><span className="avatar small">Y</span><div><strong>招聘负责人</strong><span>Hire Workbench v{workspace.config.version}</span></div></div></div></aside>
    <div className="main-shell"><header className="topbar"><div className="breadcrumb">工作空间<span>/</span><strong>{navigation.find(item => item.id === page)?.label}</strong></div><div className="topbar-tools"><span className="local-indicator"><i />{workspace.config.localOnly ? '本地工作区' : '受保护工作区'}</span><Badge tone={workspace.config.modelConfigured ? 'blue' : 'neutral'}><Sparkles size={13} />{workspace.config.modelConfigured ? '模型已配置' : '规则模式可用'}</Badge>{workspace.config.authRequired && <button className="icon-button" aria-label="退出工作区" onClick={() => void run('logout', async () => { await api('/api/session', { method: 'DELETE' }); location.reload(); })}><LogOut size={17} /></button>}</div></header>
    <main className={`main-content ${selectedCandidate ? 'detail-main' : ''}`}>
      {error && <div className="global-message error" role="alert"><AlertCircle size={19} /><div><strong>操作未完成</strong><p>{error}</p></div><button className="icon-button" aria-label="关闭错误提示" onClick={() => setError(null)}><X size={17} /></button></div>}
      {page === 'dashboard' && <Dashboard workspace={workspace} openCandidate={openCandidate} openJob={openJob} newJob={() => setJobModal({})} navigate={navigate} />}
      {page === 'jobs' && (selectedJob ? <JobDetail job={selectedJob} workspace={workspace} onBack={() => setJobId(null)} onEdit={() => setJobModal({ job: selectedJob })} onCopy={() => setJobModal({ job: selectedJob, copy: true })} onLink={() => setLinkModal({ jobId: selectedJob.id })} openCandidate={openCandidate} notify={setNotice} /> : <Jobs workspace={workspace} onNew={() => setJobModal({})} onOpen={openJob} onEdit={job => setJobModal({ job })} />)}
      {page === 'candidates' && (selectedCandidate ? <CandidateDetail candidate={selectedCandidate} workspace={workspace} run={run} busy={busy} onBack={() => setCandidateId(null)} onEdit={() => setCandidateModal({ candidate: selectedCandidate })} onLink={() => setLinkModal({ candidateId: selectedCandidate.id })} onInterview={applicationId => setInterviewModal({ applicationId })} openJob={openJob} /> : <Candidates workspace={workspace} onNew={() => setCandidateModal({})} onOpen={openCandidate} />)}
      {page === 'tasks' && <Tasks workspace={workspace} run={run} busy={busy} openCandidate={openCandidate} />}
      {page === 'interviews' && <Interviews workspace={workspace} onNew={() => setInterviewModal({})} onEdit={interview => setInterviewModal({ interview })} openCandidate={openCandidate} />}
      {page === 'settings' && <WorkspaceSettings workspace={workspace} refresh={() => void run('refresh', async () => {}, '工作区状态已刷新')} busy={busy} />}
    </main><footer className="app-footer"><span>Hire Workbench</span><span>岗位标准 · 原文证据 · 人工复核</span></footer></div>
    {notice && <div className="toast" role="status"><CheckCircle2 size={18} />{notice}<button className="icon-button" aria-label="关闭成功提示" onClick={() => setNotice(null)}><X size={15} /></button></div>}
    {jobModal && <JobForm modelConfigured={workspace.config.modelConfigured} initial={jobModal.job} copy={jobModal.copy} onClose={() => setJobModal(null)} onSaved={async job => { await refresh(); setJobModal(null); openJob(job.id); setNotice('岗位画像已保存'); }} />}
    {candidateModal && <CandidateForm candidate={candidateModal.candidate} onClose={() => setCandidateModal(null)} onSaved={async candidate => { await refresh(); setCandidateModal(null); openCandidate(candidate.id); setNotice(candidate.parseStatus === 'needs_text' ? '简历已保存，请补充可读取的原文后再分析' : '候选人资料已保存'); }} />}
    {linkModal && <LinkForm workspace={workspace} initial={linkModal} onClose={() => setLinkModal(null)} onSaved={async application => { await refresh(); setLinkModal(null); openCandidate(application.candidateId); setNotice('候选人已关联岗位'); }} />}
    {interviewModal && <InterviewForm workspace={workspace} initial={interviewModal} onClose={() => setInterviewModal(null)} onSaved={async () => { await refresh(); setInterviewModal(null); setNotice('面试安排与记录已保存'); }} />}
  </div>;
}

function Brand() { return <div className="brand"><span className="brand-mark"><span /><span /><span /></span><div><strong>Hire<span>Workbench</span></strong><small>让招聘判断，有据可依</small></div></div>; }
function Login({ onLogin }: { onLogin: () => Promise<void> }) {
  const [token, setToken] = useState(''); const [error, setError] = useState<string | null>(null); const [busy, setBusy] = useState(false);
  async function submit(event: FormEvent) { event.preventDefault(); setBusy(true); setError(null); try { await api('/api/session', json('POST', { token })); await onLogin(); } catch (err) { setError(errorText(err)); } finally { setBusy(false); } }
  return <div className="login-page"><div className="login-card"><Brand /><div className="login-symbol"><ShieldCheck size={32} /></div><h1>进入招聘工作区</h1><p>此工作区已启用访问保护，请输入部署时设置的访问令牌。</p><form onSubmit={submit}><label>工作区访问令牌<input type="password" autoComplete="current-password" value={token} onChange={event => setToken(event.target.value)} required autoFocus /></label><InlineError message={error} /><button className="button primary full" disabled={busy}>{busy ? '正在验证…' : '进入工作区'}<ArrowRight size={17} /></button></form></div></div>;
}

function Dashboard({ workspace, openCandidate, openJob, newJob, navigate }: { workspace: Workspace; openCandidate: (id: string) => void; openJob: (id: string) => void; newJob: () => void; navigate: (page: Page) => void }) {
  const pendingReviews = workspace.applications.filter(application => application.stage === 'review');
  const upcoming = workspace.interviews.filter(interview => interview.outcome === 'pending').sort((a, b) => a.scheduledAt.localeCompare(b.scheduledAt));
  const stats = [
    { label: '招聘中的岗位', value: workspace.jobs.filter(job => job.status === 'open').length, icon: Briefcase, note: `${workspace.jobs.length} 个岗位画像`, color: 'blue' },
    { label: '人才库候选人', value: workspace.candidates.length, icon: Users, note: `${workspace.candidates.filter(candidate => candidate.parseStatus === 'ready').length} 份简历可分析`, color: 'violet' },
    { label: '等待人工复核', value: pendingReviews.length, icon: ListChecks, note: '结合原文证据作出判断', color: 'amber' },
    { label: '待完成面试', value: upcoming.length, icon: CalendarDays, note: `${workspace.interviews.length} 次面试记录`, color: 'teal' },
  ];
  return <><SectionHeading title="招聘工作台" description="从明确岗位标准开始，让合适的人走到下一步。" actions={<button className="button primary" onClick={newJob}><Plus size={17} />新建岗位</button>} />
    <div className="stats-grid">{stats.map(stat => <article className="stat-card" key={stat.label}><div className="stat-top"><span>{stat.label}</span><span className={`stat-icon ${stat.color}`}><stat.icon size={19} /></span></div><strong>{stat.value.toString().padStart(2, '0')}</strong><p>{stat.note}</p></article>)}</div>
    <div className="dashboard-grid"><section className="panel pipeline-panel"><div className="panel-heading"><div><h2>招聘进展</h2><p>每一阶段，保留清晰的下一步</p></div><button className="text-button" onClick={() => navigate('candidates')}>全部候选人<ArrowRight size={15} /></button></div><div className="pipeline">{(['new', 'review', 'interview', 'offer', 'hired'] as Stage[]).map(stage => { const applications = workspace.applications.filter(application => application.stage === stage); return <div className={`pipeline-column ${stage}`} key={stage}><div className="pipeline-title"><span><i />{stageLabels[stage]}</span><b>{applications.length}</b></div><div className="pipeline-cards">{applications.slice(0, 3).map(application => { const candidate = workspace.candidates.find(item => item.id === application.candidateId); const job = workspace.jobs.find(item => item.id === application.jobId); const analysis = latestAnalysis(workspace, application.id); if (!candidate) return null; return <button className="pipeline-card" key={application.id} onClick={() => openCandidate(candidate.id)}><div className="candidate-line"><span className="avatar small">{initials(candidate.name)}</span><strong>{candidate.name}</strong></div><p>{job?.title || '未关联岗位'}</p><div className="pipeline-card-foot"><span>{analysis ? `覆盖 ${analysis.result.coverage}%` : '待分析'}</span><span>{analysis?.result.score === null || analysis?.result.score === undefined ? '—' : `${analysis.result.score} 分`}</span></div></button>; })}{applications.length === 0 && <div className="pipeline-empty">暂无候选人</div>}{applications.length > 3 && <button className="text-button pipeline-more" onClick={() => navigate('candidates')}>查看其余 {applications.length - 3} 人</button>}</div></div>; })}</div></section>
    <section className="panel focus-panel"><div className="panel-heading"><div><h2>下一步安排</h2><p>把注意力放在需要你的地方</p></div><Clock3 size={18} /></div>{pendingReviews.length > 0 && <button className="focus-item" onClick={() => navigate('candidates')}><span className="focus-icon amber"><ListChecks size={19} /></span><div><strong>{pendingReviews.length} 位候选人待复核</strong><p>查看分析证据，记录推进决定</p></div><ArrowRight size={16} /></button>}{workspace.candidates.some(candidate => candidate.parseStatus === 'needs_text') && <button className="focus-item" onClick={() => navigate('candidates')}><span className="focus-icon red"><FileText size={19} /></span><div><strong>有简历需要补充文本</strong><p>原文不足时，不执行匹配评分</p></div><ArrowRight size={16} /></button>}{upcoming.slice(0, 3).map(interview => { const application = workspace.applications.find(item => item.id === interview.applicationId); const candidate = workspace.candidates.find(item => item.id === application?.candidateId); return <button className="focus-item" key={interview.id} onClick={() => navigate('interviews')}><span className="focus-icon blue"><CalendarDays size={19} /></span><div><strong>{candidate?.name || '候选人'} · 面试</strong><p>{formatDate(interview.scheduledAt, true)} · {interview.interviewer}</p></div><ArrowRight size={16} /></button>; })}{!pendingReviews.length && !upcoming.length && !workspace.candidates.some(candidate => candidate.parseStatus === 'needs_text') && <div className="quiet-state"><CheckCircle2 size={29} /><h3>当前没有待办</h3><p>创建岗位并导入简历，开始新一轮招聘。</p></div>}<div className="focus-tip"><Sparkles size={17} /><p>分数只是参考。把“信息不足”带进面试，获得更完整的判断。</p></div></section></div>
    <section className="panel"><div className="panel-heading"><div><h2>正在招聘</h2><p>围绕岗位标准管理候选人</p></div><button className="text-button" onClick={() => navigate('jobs')}>全部岗位<ArrowRight size={15} /></button></div>{workspace.jobs.filter(job => job.status === 'open').length ? <div className="job-overview-grid">{workspace.jobs.filter(job => job.status === 'open').slice(0, 4).map(job => { const applications = workspace.applications.filter(application => application.jobId === job.id); return <button className="job-overview-card" key={job.id} onClick={() => openJob(job.id)}><span className="job-icon"><Briefcase size={21} /></span><Badge tone="green">招聘中</Badge><h3>{job.title}</h3><p>{job.department} · {job.location}</p><div className="job-overview-bottom"><span><Users size={14} />{applications.length} 位候选人</span><span>标准 v{job.version}<ArrowRight size={14} /></span></div></button>; })}</div> : <Empty title="从第一个岗位开始" description="把招聘需求整理成岗位画像，再导入候选人简历。" action={<button className="button primary" onClick={newJob}><Plus size={16} />新建岗位</button>} />}</section>
  </>;
}

function Jobs({ workspace, onNew, onOpen, onEdit }: { workspace: Workspace; onNew: () => void; onOpen: (id: string) => void; onEdit: (job: Job) => void }) {
  const [query, setQuery] = useState(''); const [status, setStatus] = useState('all');
  const list = workspace.jobs.filter(job => `${job.title} ${job.department} ${job.location}`.toLowerCase().includes(query.toLowerCase()) && (status === 'all' || job.status === status));
  return <><SectionHeading title="岗位画像" description="把用人需求变成统一、可复用的评价标准。" actions={<button className="button primary" onClick={onNew}><Plus size={17} />新建岗位</button>} /><div className="compact-stats"><span><b>{workspace.jobs.length}</b>全部岗位</span><span><i className="dot green" /><b>{workspace.jobs.filter(job => job.status === 'open').length}</b>招聘中</span><span><b>{workspace.jobs.filter(job => job.status !== 'open').length}</b>暂停 / 关闭</span></div><section className="panel"><div className="table-toolbar"><SearchBox value={query} onChange={setQuery} placeholder="搜索岗位、部门或地点" label="搜索岗位" /><label className="inline-select">岗位状态<select value={status} onChange={event => setStatus(event.target.value)}><option value="all">全部状态</option><option value="open">招聘中</option><option value="paused">已暂停</option><option value="closed">已关闭</option></select></label></div>{list.length ? <div className="table-scroll"><table><thead><tr><th>岗位名称</th><th>所属部门 / 地点</th><th>评价标准</th><th>候选人</th><th>状态</th><th>操作</th></tr></thead><tbody>{list.map(job => <tr key={job.id}><td><button className="table-title" onClick={() => onOpen(job.id)}><span className="job-icon small"><Briefcase size={17} /></span><span><strong>{job.title}</strong><small>{job.employmentType}</small></span></button></td><td><span>{job.department}</span><small className="cell-sub">{job.location}</small></td><td><span>{job.criteria.length} 个维度</span><small className="cell-sub">版本 v{job.version}</small></td><td>{workspace.applications.filter(application => application.jobId === job.id).length} 人</td><td><Badge tone={job.status === 'open' ? 'green' : 'neutral'}>{jobStatus[job.status]}</Badge></td><td><div className="row-actions"><button className="text-button" onClick={() => onOpen(job.id)}>查看</button><button className="icon-button" aria-label={`编辑 ${job.title}`} onClick={() => onEdit(job)}><Pencil size={15} /></button></div></td></tr>)}</tbody></table></div> : <Empty title={query || status !== 'all' ? '没有符合条件的岗位' : '还没有岗位画像'} description="使用模板或自行填写岗位要求与评价维度。" action={<button className="button primary" onClick={onNew}><Plus size={16} />新建岗位</button>} />}</section></>;
}

function JobDetail({ job, workspace, onBack, onEdit, onCopy, onLink, openCandidate, notify }: { job: Job; workspace: Workspace; onBack: () => void; onEdit: () => void; onCopy: () => void; onLink: () => void; openCandidate: (id: string) => void; notify: (message: string) => void }) {
  const [tab, setTab] = useState<'overview' | 'criteria' | 'candidates'>('overview');
  const applications = workspace.applications.filter(application => application.jobId === job.id);
  async function copyJD() { try { await navigator.clipboard.writeText(`${job.title}\n${job.department} · ${job.location} · ${job.employmentType}\n\n${job.description}`); notify('岗位 JD 已复制，可粘贴至招聘平台发布'); } catch { notify('浏览器未允许复制，请在岗位描述中选择文本后复制'); } }
  return <><button className="back-button" onClick={onBack}><ArrowLeft size={16} />返回岗位列表</button><SectionHeading title={job.title} description={`${job.department} · ${job.location} · ${job.employmentType}`} actions={<><button className="button secondary" onClick={onCopy}><Copy size={16} />复制岗位</button><button className="button secondary" onClick={() => void copyJD()}><Copy size={16} />复制 JD</button><button className="button primary" onClick={onEdit}><Pencil size={16} />编辑岗位</button></>} /><div className="detail-status"><Badge tone={job.status === 'open' ? 'green' : 'neutral'}>{jobStatus[job.status]}</Badge><span>岗位标准 v{job.version}</span><span>更新于 {formatDate(job.updatedAt, true)}</span></div><div className="job-detail-stats"><div><b>{applications.length}</b><span>关联候选人</span></div><div><b>{workspace.analyses.filter(analysis => applications.some(application => application.id === analysis.applicationId)).length}</b><span>分析记录</span></div><div><b>{workspace.interviews.filter(interview => applications.some(application => application.id === interview.applicationId)).length}</b><span>面试安排</span></div></div><div className="tabs" role="tablist" aria-label="岗位详情"><button role="tab" aria-selected={tab === 'overview'} className={tab === 'overview' ? 'active' : ''} onClick={() => setTab('overview')}>岗位描述</button><button role="tab" aria-selected={tab === 'criteria'} className={tab === 'criteria' ? 'active' : ''} onClick={() => setTab('criteria')}>评价标准<span>{job.criteria.length}</span></button><button role="tab" aria-selected={tab === 'candidates'} className={tab === 'candidates' ? 'active' : ''} onClick={() => setTab('candidates')}>候选人<span>{applications.length}</span></button></div>{tab === 'overview' && <div className="two-column"><section className="panel padded"><h2>岗位职责与要求</h2><div className="prose pre-wrap">{job.description}</div></section><section className="panel padded fit-height"><h2>评价维度</h2><div className="criterion-summary">{job.criteria.map(criterion => <div key={criterion.id}><span>{criterion.label}{criterion.required && <small>必需</small>}</span><b>{criterion.weight}%</b><div className="progress-track"><span style={{ width: `${criterion.weight}%` }} /></div></div>)}</div><p className="muted helper">新分析使用当前标准。历史分析保留原岗位和简历版本。</p></section></div>}{tab === 'criteria' && <section className="panel"><div className="panel-heading"><div><h2>统一的评价标准</h2><p>总权重 100%，仅考察与岗位相关的能力和经历</p></div><button className="button secondary" onClick={onEdit}><Pencil size={15} />调整标准</button></div><div className="criteria-list">{job.criteria.map(criterion => <article key={criterion.id}><div className="criterion-list-title"><h3>{criterion.label}</h3><Badge tone="blue">{criterion.weight}%</Badge>{criterion.required && <Badge tone="amber">必需项</Badge>}</div><div className="tags">{criterion.keywords.map(keyword => <span key={keyword}>{keyword}</span>)}</div></article>)}</div></section>}{tab === 'candidates' && <section className="panel"><div className="panel-heading"><div><h2>该岗位的候选人</h2><p>同一候选人可以关联多个岗位</p></div><button className="button primary" onClick={onLink}><Link2 size={16} />关联候选人</button></div>{applications.length ? <ApplicationTable applications={applications} workspace={workspace} openCandidate={openCandidate} /> : <Empty title="还没有关联候选人" description="从人才库中选择候选人，再开始岗位匹配。" action={<button className="button secondary" onClick={onLink}>关联候选人</button>} />}</section>}</>;
}
function ApplicationTable({ applications, workspace, openCandidate }: { applications: Application[]; workspace: Workspace; openCandidate: (id: string) => void }) { return <div className="table-scroll"><table><thead><tr><th>候选人</th><th>当前阶段</th><th>最近匹配</th><th>证据覆盖</th><th>操作</th></tr></thead><tbody>{applications.map(application => { const candidate = workspace.candidates.find(item => item.id === application.candidateId); const analysis = latestAnalysis(workspace, application.id); if (!candidate) return null; return <tr key={application.id}><td><button className="table-title" onClick={() => openCandidate(candidate.id)}><span className="avatar">{initials(candidate.name)}</span><span><strong>{candidate.name}</strong><small>{candidate.headline || '暂无简介'}</small></span></button></td><td><Badge tone={application.stage === 'interview' ? 'blue' : application.stage === 'hired' ? 'green' : 'neutral'}>{stageLabels[application.stage]}</Badge></td><td>{analysis ? <><strong className="score-inline">{analysis.result.score ?? '—'}</strong><small className="cell-sub">{modeLabel(analysis.mode)}</small></> : <span className="muted">待分析</span>}</td><td>{analysis ? `${analysis.result.coverage}%` : '—'}</td><td><button className="text-button" onClick={() => openCandidate(candidate.id)}>查看与复核<ArrowRight size={14} /></button></td></tr>; })}</tbody></table></div>; }

function Candidates({ workspace, onNew, onOpen }: { workspace: Workspace; onNew: () => void; onOpen: (id: string) => void }) {
  const [query, setQuery] = useState(''); const [filter, setFilter] = useState('all');
  const list = workspace.candidates.filter(candidate => `${candidate.name} ${candidate.email} ${candidate.headline} ${candidate.tags.join(' ')}`.toLowerCase().includes(query.toLowerCase()) && (filter === 'all' || filter === candidate.parseStatus || workspace.applications.some(application => application.candidateId === candidate.id && application.stage === filter)));
  return <><SectionHeading title="候选人" description="保留简历原文，围绕岗位查看每一条能力证据。" actions={<button className="button primary" onClick={onNew}><Upload size={17} />添加候选人</button>} /><section className="panel"><div className="table-toolbar"><SearchBox value={query} onChange={setQuery} placeholder="搜索姓名、技能或邮箱" label="搜索候选人" /><label className="inline-select">筛选候选人<select value={filter} onChange={event => setFilter(event.target.value)}><option value="all">全部候选人</option><option value="review">待复核</option><option value="interview">面试中</option><option value="needs_text">待补充文本</option><option value="ready">简历可分析</option></select></label></div>{list.length ? <div className="table-scroll"><table><thead><tr><th>候选人</th><th>技能标签</th><th>关联岗位</th><th>资料状态</th><th>加入时间</th><th>操作</th></tr></thead><tbody>{list.map(candidate => { const applications = workspace.applications.filter(application => application.candidateId === candidate.id); return <tr key={candidate.id}><td><button className="table-title" onClick={() => onOpen(candidate.id)}><span className="avatar">{initials(candidate.name)}</span><span><strong>{candidate.name}</strong><small>{candidate.headline || candidate.email || '暂无简介'}</small></span></button></td><td><div className="tags compact">{candidate.tags.slice(0, 3).map(tag => <span key={tag}>{tag}</span>)}{!candidate.tags.length && <span className="muted">—</span>}</div></td><td>{applications.length ? <div className="job-names">{applications.slice(0, 2).map(application => <span key={application.id}>{workspace.jobs.find(job => job.id === application.jobId)?.title}</span>)}{applications.length > 2 && <small>另外 {applications.length - 2} 个岗位</small>}</div> : <span className="muted">未关联</span>}</td><td><Badge tone={candidate.parseStatus === 'ready' ? 'green' : 'amber'}>{candidate.parseStatus === 'ready' ? '可分析' : '待补充文本'}</Badge><small className="cell-sub">简历 v{candidate.resumeVersion}</small></td><td>{formatDate(candidate.createdAt)}</td><td><button className="text-button" onClick={() => onOpen(candidate.id)}>查看与复核<ArrowRight size={14} /></button></td></tr>; })}</tbody></table></div> : <Empty title={query || filter !== 'all' ? '没有符合条件的候选人' : '让第一份简历进入工作区'} description="上传 PDF、DOCX、TXT，或直接粘贴简历文本。" action={<button className="button primary" onClick={onNew}><Upload size={16} />添加候选人</button>} />}<div className="table-footer">共 {list.length} 位候选人<span>可按姓名、技能和岗位持续整理</span></div></section></>;
}

function CandidateDetail({ candidate, workspace, run, busy, onBack, onEdit, onLink, onInterview, openJob }: { candidate: Candidate; workspace: Workspace; run: RunAction; busy: string; onBack: () => void; onEdit: () => void; onLink: () => void; onInterview: (applicationId: string) => void; openJob: (jobId: string) => void }) {
  const applications = workspace.applications.filter(application => application.candidateId === candidate.id);
  const [appId, setAppId] = useState(applications[0]?.id || '');
  const application = applications.find(item => item.id === appId) || applications[0];
  const job = workspace.jobs.find(item => item.id === application?.jobId);
  const analyses = workspace.analyses.filter(analysis => analysis.applicationId === application?.id).sort((a, b) => b.createdAt.localeCompare(a.createdAt));
  const [analysisId, setAnalysisId] = useState('');
  const analysis = analyses.find(item => item.id === analysisId) || analyses[0];
  const [highlight, setHighlight] = useState<Evidence | null>(null);
  const evidenceMark = useRef<HTMLElement>(null);
  const [mode, setMode] = useState<AnalysisMode>(workspace.config.modelConfigured ? workspace.config.mode : 'rules');
  const tasks = workspace.tasks.filter(task => task.applicationId === application?.id).sort((a, b) => b.createdAt.localeCompare(a.createdAt));
  const activeTask = tasks.find(task => task.status === 'running' || task.status === 'queued');
  const newestTask = tasks[0];
  const source = analysis?.resumeSnapshot || candidate;
  const stale = analysis && (analysis.jobVersion !== job?.version || analysis.resumeVersion !== candidate.resumeVersion);
  useEffect(() => { setAnalysisId(''); setHighlight(null); }, [application?.id]);
  useEffect(() => { setHighlight(null); }, [analysis?.id]);
  useEffect(() => { evidenceMark.current?.scrollIntoView({ behavior: 'smooth', block: 'center' }); }, [highlight]);
  const reviews = workspace.reviews.filter(review => review.applicationId === application?.id).sort((a, b) => b.createdAt.localeCompare(a.createdAt));
  async function analyze() { if (!application) return; const ok = await run('analyze', () => api(`/api/applications/${application.id}/analyze`, json('POST', { mode })), '分析任务已提交，结果会自动更新'); if (ok) setAnalysisId(''); }
  return <><button className="back-button" onClick={onBack}><ArrowLeft size={16} />返回候选人列表</button><div className="candidate-profile"><span className="avatar large">{initials(candidate.name)}</span><div className="candidate-profile-body"><div className="candidate-profile-title"><h1>{candidate.name}</h1><Badge tone={candidate.parseStatus === 'ready' ? 'green' : 'amber'}>{candidate.parseStatus === 'ready' ? '简历可分析' : '待补充文本'}</Badge></div><p>{candidate.headline || '尚未填写个人简介'}</p><div className="profile-meta">{candidate.email && <span>{candidate.email}</span>}{candidate.phone && <span>{candidate.phone}</span>}<span>当前简历 v{candidate.resumeVersion}</span></div></div><button className="button secondary" onClick={onEdit}><Pencil size={16} />编辑资料 / 简历</button></div>
    {candidate.parseStatus === 'needs_text' && <div className="notice-banner amber"><AlertCircle size={18} /><div><strong>这份简历需要补充可读取的文本</strong><p>{candidate.parseMessage || '文件中没有足够的可读取文本。请编辑简历并粘贴正文，或上传文本型 PDF / DOCX。'} 扫描件不会被当作已成功解析。</p></div><button className="button secondary" onClick={onEdit}>补充文本</button></div>}
    <div className="application-switch"><div className="application-tabs">{applications.map(item => <button key={item.id} className={application?.id === item.id ? 'active' : ''} onClick={() => setAppId(item.id)}><Briefcase size={15} />{workspace.jobs.find(j => j.id === item.jobId)?.title || '岗位'}<span>{stageLabels[item.stage]}</span></button>)}</div><button className="text-button" onClick={onLink}><Plus size={15} />关联岗位</button></div>
    {!application ? <section className="panel"><Empty title="先为候选人选择一个岗位" description="关联岗位后，就可以依据该岗位的标准进行匹配、人工复核和面试。" action={<button className="button primary" onClick={onLink}><Link2 size={16} />关联岗位</button>} /><div className="unlinked-resume"><h2>当前简历原文</h2><pre>{candidate.resumeText || '尚无可读取的文本'}</pre></div></section> : <>
      <div className="analysis-toolbar"><div className="analysis-toolbar-title"><span className="eyebrow">候选人评估</span><button className="text-button" onClick={() => job && openJob(job.id)}>查看岗位标准 v{job?.version}<ArrowRight size={13} /></button></div><div className="analysis-toolbar-controls"><label className="inline-select"><span className="sr-only">分析方式</span><select aria-label="分析方式" value={mode} onChange={event => setMode(event.target.value as AnalysisMode)}><option value="rules">规则辅助（不调用模型）</option><option value="llm" disabled={!workspace.config.modelConfigured}>AI 模型分析{!workspace.config.modelConfigured ? '（未配置）' : ''}</option></select></label><button className="button primary" onClick={() => void analyze()} disabled={!!activeTask || busy === 'analyze' || candidate.parseStatus !== 'ready'}><Sparkles size={16} />{activeTask ? '正在分析…' : analyses.length ? '重新分析' : '开始分析'}</button><label className="inline-select"><span className="sr-only">招聘阶段</span><select aria-label="招聘阶段" value={application.stage} disabled={busy === 'stage'} onChange={event => void run('stage', () => api(`/api/applications/${application.id}`, json('PATCH', { stage: event.target.value })), '招聘阶段已更新')}>{Object.entries(stageLabels).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></label></div></div>
      {activeTask && <div className="notice-banner blue" role="status"><span className="spinner small" /><div><strong>{activeTask.status === 'queued' ? '任务已进入队列' : '正在分析岗位与简历'}</strong><p>你可以切换页面。任务状态和结果会保存，并在这里自动更新。</p></div></div>}
      {newestTask?.status === 'failed' && <div className="notice-banner red" role="alert"><AlertCircle size={19} /><div><strong>最近一次分析未完成</strong><p>{newestTask.error || '任务执行失败，请重试。'}</p></div><button className="button secondary" disabled={!!busy} onClick={() => void run('retry', () => api(`/api/tasks/${newestTask.id}/retry`, { method: 'POST' }), '已按原始输入重试分析')}><RefreshCw size={15} />重试</button></div>}
      {stale && <div className="notice-banner amber compact"><Clock3 size={17} /><p>当前查看的是历史快照：岗位 v{analysis.jobVersion} / 简历 v{analysis.resumeVersion}。资料已更新，可重新分析，历史结论保持不变。</p></div>}
      <div className="review-workspace"><section className="panel resume-panel"><div className="panel-heading"><div><h2><FileText size={17} />简历原文</h2><p>{analysis ? '本次分析使用的资料快照' : '当前候选人资料'} · v{source.resumeVersion}</p></div>{highlight && <button className="text-button" onClick={() => setHighlight(null)}>取消高亮</button>}</div><div className="resume-source"><span>{source.sourceFile || '手动录入的简历'}</span><Badge tone="neutral">原始文本</Badge></div><div className="resume-text" data-testid="resume-text">{source.resumeText ? <pre>{highlight && highlight.start >= 0 && highlight.end <= source.resumeText.length ? <>{source.resumeText.slice(0, highlight.start)}<mark ref={evidenceMark}>{source.resumeText.slice(highlight.start, highlight.end)}</mark>{source.resumeText.slice(highlight.end)}</> : source.resumeText}</pre> : <p className="muted">尚无可读取的简历原文，请先补充文本。</p>}</div><div className="resume-foot"><ShieldCheck size={14} />点击右侧证据，可回到原文对应位置</div></section>
      <section className="analysis-column">{analysis ? <><div className="panel result-summary"><div className="result-top"><div><h2>匹配分析</h2><Badge tone={analysis.mode === 'llm' ? 'blue' : 'neutral'}>{modeLabel(analysis.mode)}</Badge></div><a className="icon-button" aria-label="导出当前分析报告" href={`/api/analyses/${analysis.id}/export`} download><Download size={18} /></a></div><div className="result-scores"><div className="main-score"><strong>{analysis.result.score ?? '—'}</strong><span>{analysis.result.score === null ? '暂不评分' : '参考匹配分'}</span></div><div className="coverage-score"><span>证据覆盖率<b>{analysis.result.coverage}%</b></span><div className="progress-track"><span style={{ width: `${Math.max(0, Math.min(100, analysis.result.coverage))}%` }} /></div><small>信息不足项保留为待核实</small></div></div><p className="analysis-summary">{analysis.result.summary}</p><label className="history-select">分析版本<select aria-label="分析历史版本" value={analysis.id} onChange={event => setAnalysisId(event.target.value)}>{analyses.map((item, index) => <option key={item.id} value={item.id}>{index === 0 ? '最新 · ' : ''}{formatDate(item.createdAt, true)} · 岗位 v{item.jobVersion} / 简历 v{item.resumeVersion}</option>)}</select></label>{analysis.result.warnings.length > 0 && <div className="analysis-warnings">{analysis.result.warnings.map((warning, index) => <p key={index}><AlertCircle size={14} />{warning}</p>)}</div>}</div><div className="dimension-header"><h2>逐项评价</h2><span>{analysis.result.assessments.length} 个维度 · 点击证据定位原文</span></div>{analysis.result.assessments.map(assessment => <article className={`panel assessment ${assessment.status}`} key={assessment.criterionId}><header><div><h3>{assessment.label}</h3><span>权重 {assessment.weight}%{assessment.required ? ' · 必需项' : ''}</span></div><Badge tone={assessment.status}>{statusLabels[assessment.status]}</Badge></header><p>{assessment.rationale}</p>{assessment.evidence.length ? <div className="evidence-list">{assessment.evidence.map((evidence, index) => <button key={`${evidence.start}-${index}`} className={`evidence-quote ${highlight === evidence ? 'selected' : ''}`} onClick={() => setHighlight(evidence)}><span>原文证据<ArrowRight size={13} /></span><q>{evidence.quote}</q></button>)}</div> : <div className="no-evidence">未找到足够的简历证据，保留为面试核实项。</div>}{assessment.question && <div className="question-line"><span>建议追问</span><p>{assessment.question}</p></div>}</article>)}</> : <section className="panel"><Empty title="还没有匹配分析" description={candidate.parseStatus !== 'ready' ? '请先补充可读取的简历文本。' : '按岗位标准逐项查看证据，再决定下一步。规则辅助无需模型密钥。'} action={<button className="button primary" disabled={!!activeTask || candidate.parseStatus !== 'ready'} onClick={() => void analyze()}><Sparkles size={16} />开始分析</button>} /><div className="analysis-principles"><span><Check size={15} />标准来自岗位画像</span><span><Check size={15} />结论关联简历原文</span><span><Check size={15} />信息不足不等于不具备能力</span></div></section>}</section>
      <aside className="review-column"><section className="panel padded review-panel"><h2><ShieldCheck size={17} />人工复核</h2><p className="muted helper">结合岗位要求与原文，记录你的判断。</p><ReviewForm key={`${application.id}-${analysis?.id || ''}`} application={application} analysis={analysis} run={run} busy={busy} /><div className="review-divider" /><button className="button secondary full" onClick={() => onInterview(application.id)}><CalendarDays size={16} />安排面试</button></section>{analysis?.result.questions.length ? <section className="panel padded"><h2>面试准备</h2><p className="muted helper">优先验证信息缺口与实际承担的工作。</p><ol className="question-list">{analysis.result.questions.map((question, index) => <li key={index}>{question}</li>)}</ol></section> : null}<section className="panel padded"><h2>复核记录<span className="count">{reviews.length}</span></h2>{reviews.length ? <div className="review-history">{reviews.map(review => <article key={review.id}><div><strong>{review.reviewer}</strong><Badge tone={review.decision === 'advance' ? 'green' : review.decision === 'reject' ? 'red' : 'amber'}>{review.decision === 'advance' ? '推进面试' : review.decision === 'reject' ? '不推进' : '待核实'}</Badge></div><p>{review.note}</p><small>{formatDate(review.createdAt, true)} · {review.analysisId ? '关联分析快照' : '人工判断'}</small></article>)}</div> : <p className="muted helper">尚无复核记录。</p>}</section></aside></div>
    </>}</>;
}

function ReviewForm({ application, analysis, run, busy }: { application: Application; analysis?: Analysis; run: RunAction; busy: string }) {
  const [reviewer, setReviewer] = useState('招聘负责人'); const [decision, setDecision] = useState('hold'); const [note, setNote] = useState('');
  async function submit(event: FormEvent) { event.preventDefault(); const ok = await run('review', () => api(`/api/applications/${application.id}/reviews`, json('POST', { ...(analysis ? { analysisId: analysis.id } : {}), reviewer, decision, note })), '复核已记录，招聘阶段已同步'); if (ok) setNote(''); }
  return <form onSubmit={submit} className="stack-form"><label>复核人<input value={reviewer} onChange={event => setReviewer(event.target.value)} required maxLength={100} /></label><label>复核结论<select aria-label="复核结论" value={decision} onChange={event => setDecision(event.target.value)}><option value="hold">待核实</option><option value="advance">推进面试</option><option value="reject">不推进</option></select></label><label>判断与下一步<textarea aria-label="复核说明" value={note} onChange={event => setNote(event.target.value)} placeholder="例如：项目经历有依据，独立部署能力需在面试中验证。" required minLength={3} rows={4} maxLength={5000} /></label><button className="button primary full" disabled={busy === 'review'}><CheckCircle2 size={16} />{busy === 'review' ? '正在保存…' : '保存复核'}</button></form>;
}

function Tasks({ workspace, run, busy, openCandidate }: { workspace: Workspace; run: RunAction; busy: string; openCandidate: (id: string) => void }) {
  const [filter, setFilter] = useState('all'); const tasks = [...workspace.tasks].filter(task => filter === 'all' || task.status === filter).sort((a, b) => b.createdAt.localeCompare(a.createdAt));
  return <><SectionHeading title="匹配任务" description="任务与输入版本一同保存；失败可追踪，结果可复核。" /><div className="compact-stats"><span><b>{workspace.tasks.length}</b>全部任务</span><span><i className="dot blue" /><b>{workspace.tasks.filter(task => task.status === 'queued' || task.status === 'running').length}</b>处理中</span><span><i className="dot green" /><b>{workspace.tasks.filter(task => task.status === 'succeeded').length}</b>已完成</span><span><i className="dot red" /><b>{workspace.tasks.filter(task => task.status === 'failed').length}</b>失败</span></div><section className="panel"><div className="table-toolbar"><h2>分析任务记录</h2><label className="inline-select">任务状态<select value={filter} onChange={event => setFilter(event.target.value)}><option value="all">全部状态</option>{Object.entries(taskStatus).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></label></div>{tasks.length ? <div className="task-list">{tasks.map(task => { const application = workspace.applications.find(item => item.id === task.applicationId); const candidate = workspace.candidates.find(item => item.id === application?.candidateId); const job = workspace.jobs.find(item => item.id === application?.jobId); return <article className="task-item" key={task.id}><div className={`task-icon ${task.status}`}>{task.status === 'succeeded' ? <CheckCircle2 size={20} /> : task.status === 'failed' ? <AlertCircle size={20} /> : <Clock3 size={20} />}</div><div className="task-content"><div className="task-title"><strong>{candidate?.name || '候选人'}<span>→</span>{job?.title || '岗位'}</strong><Badge tone={task.status === 'succeeded' ? 'green' : task.status === 'failed' ? 'red' : 'blue'}>{taskStatus[task.status]}</Badge></div><p>{modeLabel(task.mode)} · 尝试 {task.attempts} 次 · {formatDate(task.createdAt, true)}</p>{task.error && <div className="task-error">{task.error}</div>}</div><div className="row-actions">{task.status === 'failed' && <button className="button secondary" disabled={!!busy} onClick={() => void run(`retry-${task.id}`, () => api(`/api/tasks/${task.id}/retry`, { method: 'POST' }), '任务已按原始输入重新提交')}><RefreshCw size={15} />重试</button>}{candidate && <button className="text-button" onClick={() => openCandidate(candidate.id)}>查看候选人<ArrowRight size={14} /></button>}</div></article>; })}</div> : <Empty title="还没有匹配任务" description="在候选人工作区选择岗位并开始分析，任务会显示在这里。" />}</section></>;
}

function Interviews({ workspace, onNew, onEdit, openCandidate }: { workspace: Workspace; onNew: () => void; onEdit: (interview: Interview) => void; openCandidate: (id: string) => void }) {
  const [filter, setFilter] = useState('all'); const list = [...workspace.interviews].filter(interview => filter === 'all' || interview.outcome === filter).sort((a, b) => a.scheduledAt.localeCompare(b.scheduledAt));
  return <><SectionHeading title="面试管理" description="带着需要验证的问题进入面试，把真实观察带回评价。" actions={<button className="button primary" disabled={!workspace.applications.length} onClick={onNew}><Plus size={17} />安排面试</button>} /><section className="panel"><div className="table-toolbar"><h2>面试安排与记录</h2><label className="inline-select">面试结果<select value={filter} onChange={event => setFilter(event.target.value)}><option value="all">全部面试</option>{Object.entries(outcomeLabels).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></label></div>{list.length ? <div className="interview-list">{list.map(interview => { const application = workspace.applications.find(item => item.id === interview.applicationId); const candidate = workspace.candidates.find(item => item.id === application?.candidateId); const job = workspace.jobs.find(item => item.id === application?.jobId); const date = new Date(interview.scheduledAt); return <article className="interview-card" key={interview.id}><div className="date-tile"><span>{date.getMonth() + 1} 月</span><strong>{date.getDate()}</strong><small>{date.toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' })}</small></div><div className="interview-content"><div className="interview-title"><button className="text-button strong" onClick={() => candidate && openCandidate(candidate.id)}>{candidate?.name || '候选人'}</button><Badge tone={interview.outcome === 'pass' ? 'green' : interview.outcome === 'reject' ? 'red' : interview.outcome === 'hold' ? 'amber' : 'blue'}>{outcomeLabels[interview.outcome]}</Badge></div><h3>{job?.title || '岗位'}</h3><p>{interview.interviewer} · {interview.location || '地点 / 会议链接待补充'}</p>{interview.notes && <div className="interview-notes">{interview.notes}</div>}</div><button className="button secondary" onClick={() => onEdit(interview)}><Pencil size={15} />{interview.outcome === 'pending' ? '填写记录' : '查看 / 编辑'}</button></article>; })}</div> : <Empty title="还没有面试安排" description={workspace.applications.length ? '从已关联岗位的候选人中选择，为面试准备好时间与问题。' : '先添加候选人并关联岗位，再安排面试。'} action={workspace.applications.length ? <button className="button secondary" onClick={onNew}>安排面试</button> : undefined} />}</section></>;
}

function WorkspaceSettings({ workspace, refresh, busy }: { workspace: Workspace; refresh: () => void; busy: string }) {
  return <><SectionHeading title="工作区设置" description="查看运行状态、模型配置与数据记录。" actions={<button className="button secondary" onClick={refresh} disabled={!!busy}><RefreshCw size={16} />刷新状态</button>} /><div className="settings-grid"><section className="panel padded"><div className="settings-icon blue"><Sparkles size={22} /></div><h2>分析能力</h2><p className="muted">规则辅助可直接使用。AI 模式使用服务端配置的模型。</p><dl className="settings-list"><div><dt>规则模式</dt><dd><Badge tone="green">已就绪</Badge></dd></div><div><dt>模型连接配置</dt><dd><Badge tone={workspace.config.modelConfigured ? 'blue' : 'amber'}>{workspace.config.modelConfigured ? '已配置' : '未配置'}</Badge></dd></div><div><dt>模型名称</dt><dd>{workspace.config.model || '—'}</dd></div><div><dt>默认分析方式</dt><dd>{modeLabel(workspace.config.mode)}</dd></div></dl><div className="settings-note"><strong>启用 AI 模型分析</strong><p>在部署目录的 .env 中设置 LLM_BASE_URL、LLM_API_KEY、LLM_MODEL 后重启服务。访问密钥只保存在服务端，不会显示在页面。</p><p>“已配置”表示参数已提供，实际可用性以分析任务结果为准。失败不会自动替换成模拟结果。</p></div></section><section className="panel padded"><div className="settings-icon teal"><ShieldCheck size={22} /></div><h2>工作区与数据</h2><p className="muted">单工作区运行，所有更改与任务状态持续保存。</p><dl className="settings-list"><div><dt>版本</dt><dd>v{workspace.config.version}</dd></div><div><dt>访问范围</dt><dd>{workspace.config.localOnly ? '本机访问' : '网络访问'}</dd></div><div><dt>访问保护</dt><dd><Badge tone={workspace.config.authRequired ? 'green' : 'neutral'}>{workspace.config.authRequired ? '已启用令牌认证' : '本机模式'}</Badge></dd></div><div><dt>分析快照</dt><dd>{workspace.analyses.length} 份</dd></div></dl><a className="button secondary" href="/api/export" download><Download size={16} />导出工作区 JSON</a><p className="helper muted">导出包括业务记录，包含候选人资料，请妥善保管。完整恢复还需备份 data 目录中的数据库。</p></section></div><section className="panel"><div className="panel-heading"><div><h2>最近操作</h2><p>记录资料变化、分析任务与人工决定</p></div><span className="muted">{workspace.audit.length} 条记录</span></div>{workspace.audit.length ? <div className="table-scroll"><table><thead><tr><th>操作</th><th>内容</th><th>时间</th></tr></thead><tbody>{[...workspace.audit].sort((a, b) => b.createdAt.localeCompare(a.createdAt)).slice(0, 30).map(event => <tr key={event.id}><td><code className="audit-action">{event.action}</code></td><td>{event.detail}</td><td className="nowrap">{formatDate(event.createdAt, true)}</td></tr>)}</tbody></table></div> : <Empty title="尚无操作记录" description="创建岗位或候选人后，相关操作会保存在这里。" />}</section></>;
}
function SearchBox({ value, onChange, placeholder, label }: { value: string; onChange: (value: string) => void; placeholder: string; label: string }) { return <div className="search-box"><Search size={17} /><input type="search" aria-label={label} value={value} onChange={event => onChange(event.target.value)} placeholder={placeholder} /></div>; }

const defaultCriteria: Criterion[] = [
  { id: 'development', label: '开发与交付', weight: 35, required: true, keywords: ['TypeScript', 'React', 'Node.js', 'Go', 'Docker', '部署'] },
  { id: 'security', label: '安全实践', weight: 25, required: false, keywords: ['漏洞', '安全测试', 'WAF', '渗透测试', '安全运营'] },
  { id: 'requirements', label: '需求理解与协作', weight: 20, required: true, keywords: ['需求', '客户', '方案', '交付', '协作'] },
  { id: 'ai', label: 'AI 工程实践', weight: 20, required: false, keywords: ['LLM', 'Agent', '大模型', 'RAG', '工具调用', '评测'] },
];
const templates: Record<string, JobDraft> = {
  fde: { title: 'FDE 开发实习生', department: '技术交付团队', location: '北京 / 远程', employmentType: '实习', description: '岗位职责\n1. 将客户的业务需求拆解为可验证的产品功能。\n2. 使用 TypeScript 或 Go 完成接口、页面与部署，记录实现与验证过程。\n3. 接入大模型与安全工具，构建可演示、可复核的业务闭环。\n\n任职要求\n- 有实际项目或课程作品，能说明本人承担的工作。\n- 掌握 Git、HTTP API 与基本数据库操作。\n- 能清楚表达问题，主动记录失败原因与改进方式。\n\n加分项\n网络安全实践、LLM 工具调用、自动化测试或容器部署经验。', status: 'open', criteria: defaultCriteria },
  presales: { title: '安全技术售前工程师', department: '解决方案团队', location: '北京', employmentType: '全职', description: '岗位职责\n1. 理解客户的安全建设目标，梳理业务、资产与安全运营需求。\n2. 编写解决方案与技术材料，完成产品演示和 PoC 验证。\n3. 与销售、研发、交付团队协作，推动方案落地。\n\n任职要求\n- 具备网络安全基础知识和实际项目经验。\n- 能将技术能力转化为客户可理解的业务价值。\n- 能清楚说明项目角色、方案取舍、验证方法与交付结果。\n\n加分项\n运营商项目、安全运营、暴露面治理或 AI 安全应用经验。', status: 'open', criteria: [
    { id: 'security', label: '安全技术理解', weight: 30, required: true, keywords: ['WAF', 'SOC', '漏洞', '安全运营', '暴露面', '攻防'] },
    { id: 'solution', label: '方案与需求分析', weight: 30, required: true, keywords: ['方案', '需求', '架构', '技术规范', '客户'] },
    { id: 'poc', label: '验证与交付实践', weight: 25, required: true, keywords: ['PoC', '测试', '验证', '部署', '交付'] },
    { id: 'collaboration', label: '沟通与协作', weight: 15, required: false, keywords: ['汇报', '演示', '协作', '协调', '培训'] },
  ] },
};
function JobForm({ initial, copy, modelConfigured, onClose, onSaved }: { initial?: Job; copy?: boolean; modelConfigured: boolean; onClose: () => void; onSaved: (job: Job) => Promise<void> }) {
  const starting = initial ? { ...initial, title: copy ? `${initial.title}（副本）` : initial.title } : templates.fde;
  const [draft, setDraft] = useState<JobDraft>(() => ({ title: starting.title, department: starting.department, location: starting.location, employmentType: starting.employmentType, description: starting.description, status: starting.status, criteria: structuredClone(starting.criteria) }));
  const [criteria, setCriteria] = useState(() => starting.criteria.map(criterion => ({ ...criterion, keywordText: criterion.keywords.join('，') })));
  const [template, setTemplate] = useState('fde'); const [busy, setBusy] = useState(false); const [error, setError] = useState<string | null>(null);
  const [requirements, setRequirements] = useState(''); const [draftBusy, setDraftBusy] = useState(false); const [draftNotice, setDraftNotice] = useState<string | null>(null);
  async function createAIDraft() { setError(null); setDraftNotice(null); setDraftBusy(true); try { const result = await api<{title: string; description: string; criteria: Criterion[]; notice: string}>('/api/jobs/draft', json('POST', { requirements })); setDraft(current => ({ ...current, title: result.title, description: result.description, criteria: result.criteria })); setCriteria(result.criteria.map(criterion => ({ ...criterion, keywordText: criterion.keywords.join('，') }))); setDraftNotice(result.notice || 'AI 草稿已填入下方表单，请检查并修改后保存。'); } catch (err) { setError(errorText(err)); } finally { setDraftBusy(false); } }
  const total = criteria.reduce((sum, criterion) => sum + Number(criterion.weight || 0), 0);
  function applyTemplate() { const next = templates[template]; setDraft({ ...next, criteria: structuredClone(next.criteria) }); setCriteria(next.criteria.map(criterion => ({ ...criterion, keywordText: criterion.keywords.join('，') }))); }
  function updateCriterion(index: number, change: Partial<typeof criteria[number]>) { setCriteria(current => current.map((criterion, i) => i === index ? { ...criterion, ...change } : criterion)); }
  async function submit(event: FormEvent) { event.preventDefault(); setError(null); if (Math.abs(total - 100) > 0.001) { setError('评价维度的权重之和必须等于 100%。'); return; } if (!criteria.length || criteria.length > 12) { setError('请保留 1–12 个评价维度。'); return; } for (const criterion of criteria) { const keywords = criterion.keywordText.split(/[,，、\n]/).map(value => value.trim()).filter(Boolean); if (!keywords.length || keywords.length > 20 || keywords.some(keyword => keyword.length > 60)) { setError('每个维度需要 1–20 个关键词，每个关键词最多 60 个字符。'); return; } } setBusy(true); try { const payload = { ...draft, criteria: criteria.map(({ keywordText, ...criterion }) => ({ ...criterion, weight: Number(criterion.weight), keywords: keywordText.split(/[,，、\n]/).map(value => value.trim()).filter(Boolean) })) }; const job = await api<Job>(initial && !copy ? `/api/jobs/${initial.id}` : '/api/jobs', json(initial && !copy ? 'PUT' : 'POST', payload)); await onSaved(job); } catch (err) { setError(errorText(err)); } finally { setBusy(false); } }
  return <Modal title={initial && !copy ? '编辑岗位画像' : copy ? '复制岗位画像' : '新建岗位画像'} subtitle="先确定岗位职责，再用评价标准统一后续判断。" onClose={onClose} wide><form onSubmit={submit}><div className="modal-body"><details className="ai-draft"><summary><Sparkles size={17} /><span>AI 辅助起草岗位</span><Badge tone={modelConfigured ? 'blue' : 'neutral'}>{modelConfigured ? '模型已配置' : '未配置模型'}</Badge></summary><div><label>描述你的招聘需求<textarea value={requirements} onChange={event => setRequirements(event.target.value)} rows={3} maxLength={12000} placeholder="例如：招一位 FDE 实习生，会 TypeScript，能把客户需求做成可验证的 AI 安全应用。" /></label><div className="ai-draft-actions"><p>{modelConfigured ? '草稿只填入下方表单，由你确认后保存。' : '配置模型后可使用；当前仍可应用模板或手动填写。'}</p><button type="button" className="button secondary" onClick={() => void createAIDraft()} disabled={!modelConfigured || draftBusy || requirements.trim().length < 10}><Sparkles size={15} />{draftBusy ? '正在起草…' : '生成岗位草稿'}</button></div>{draftNotice && <div className="notice-banner blue compact" role="status"><CheckCircle2 size={16} /><p>{draftNotice}</p></div>}</div></details><div className="template-picker"><div><Sparkles size={18} /><span>从可编辑模板开始</span></div><select aria-label="岗位模板" value={template} onChange={event => setTemplate(event.target.value)}><option value="fde">FDE 开发实习生</option><option value="presales">安全技术售前</option></select><button type="button" className="button secondary" onClick={applyTemplate}>应用模板</button></div><div className="form-section"><h3><span>01</span>岗位基本信息</h3><div className="form-grid"><label>岗位名称<input aria-label="岗位名称" value={draft.title} onChange={event => setDraft({ ...draft, title: event.target.value })} required maxLength={120} /></label><label>所属部门<input value={draft.department} onChange={event => setDraft({ ...draft, department: event.target.value })} required maxLength={100} /></label><label>工作地点<input value={draft.location} onChange={event => setDraft({ ...draft, location: event.target.value })} required maxLength={100} /></label><label>用工类型<select value={draft.employmentType} onChange={event => setDraft({ ...draft, employmentType: event.target.value })}><option>全职</option><option>实习</option><option>兼职</option><option>项目制</option></select></label><label>岗位状态<select aria-label="岗位状态" value={draft.status} onChange={event => setDraft({ ...draft, status: event.target.value as Job['status'] })}><option value="open">招聘中</option><option value="paused">暂停招聘</option><option value="closed">已关闭</option></select></label></div><label>岗位职责与要求<textarea aria-label="岗位职责与要求" value={draft.description} onChange={event => setDraft({ ...draft, description: event.target.value })} rows={8} required minLength={20} maxLength={20000} /></label></div><div className="form-section"><div className="form-section-title"><h3><span>02</span>个性化评价标准</h3><Badge tone={Math.abs(total - 100) < 0.001 ? 'green' : 'red'}>权重合计 {total}% / 100%</Badge></div><p className="muted helper">关键词用于规则辅助的证据检索；真实能力仍需结合项目职责与面试验证。不要加入年龄、性别等与岗位无关的条件。</p><div className="criteria-editor">{criteria.map((criterion, index) => <div className="criterion-editor-row" key={criterion.id}><div className="criterion-editor-main"><label>维度 {index + 1}<input aria-label={`评价维度 ${index + 1}`} value={criterion.label} onChange={event => updateCriterion(index, { label: event.target.value })} required minLength={2} maxLength={120} /></label><label>权重 %<input aria-label={`维度权重 ${index + 1}`} type="number" min="1" max="100" step="1" value={criterion.weight} onChange={event => updateCriterion(index, { weight: Number(event.target.value) })} required /></label><label className="checkbox-label"><input type="checkbox" checked={criterion.required} onChange={event => updateCriterion(index, { required: event.target.checked })} />必需项</label><button className="icon-button danger" type="button" aria-label={`移除维度 ${index + 1}`} onClick={() => setCriteria(current => current.filter((_, i) => i !== index))} disabled={criteria.length <= 1}><Trash2 size={16} /></button></div><label className="keyword-label">相关关键词（用逗号分隔）<input aria-label={`维度关键词 ${index + 1}`} value={criterion.keywordText} onChange={event => updateCriterion(index, { keywordText: event.target.value })} required placeholder="例如：TypeScript，接口，部署" /></label></div>)}</div><button type="button" className="text-button" disabled={criteria.length >= 12} onClick={() => setCriteria(current => [...current, { id: crypto.randomUUID(), label: '', weight: 10, required: false, keywords: [], keywordText: '' }])}><Plus size={16} />增加评价维度</button></div>{initial && !copy && <div className="notice-banner blue compact"><Clock3 size={16} /><p>保存后将生成新的岗位版本，已有分析的标准与结论会继续保留。</p></div>}<InlineError message={error} /></div><footer className="modal-footer"><span>权重总和需要为 100%</span><div><button type="button" className="button secondary" onClick={onClose}>取消</button><button className="button primary" disabled={busy || draftBusy || Math.abs(total - 100) > 0.001}>{busy ? '正在保存…' : '保存岗位'}</button></div></footer></form></Modal>;
}

function CandidateForm({ candidate, onClose, onSaved }: { candidate?: Candidate; onClose: () => void; onSaved: (candidate: Candidate) => Promise<void> }) {
  const [tab, setTab] = useState<'text' | 'file'>('text');
  const [draft, setDraft] = useState({ name: candidate?.name || '', email: candidate?.email || '', phone: candidate?.phone || '', headline: candidate?.headline || '', tags: candidate?.tags.join('，') || '', resumeText: candidate?.resumeText || '' });
  const [file, setFile] = useState<File | null>(null); const [busy, setBusy] = useState(false); const [error, setError] = useState<string | null>(null);
  async function submit(event: FormEvent) { event.preventDefault(); setBusy(true); setError(null); try { let result: Candidate; if (tab === 'text') { const tags = draft.tags.split(/[,，、]/).map(tag => tag.trim()).filter(Boolean); if (tags.length > 20 || tags.some(tag => tag.length > 40)) throw new Error('最多填写 20 个标签，每个标签最多 40 个字符。'); if (draft.resumeText.trim().length < 50) throw new Error('请补充至少 50 个字符的简历原文。'); } if (tab === 'file' && !candidate) { if (!file) throw new Error('请先选择简历文件。'); const body = new FormData(); body.append('file', file); if (draft.name.trim()) body.append('name', draft.name.trim()); result = await api<Candidate>('/api/candidates/upload', { method: 'POST', body }); } else { result = await api<Candidate>(candidate ? `/api/candidates/${candidate.id}` : '/api/candidates', json(candidate ? 'PUT' : 'POST', { ...draft, tags: draft.tags.split(/[,，、]/).map(tag => tag.trim()).filter(Boolean) })); } await onSaved(result); } catch (err) { setError(errorText(err)); } finally { setBusy(false); } }
  return <Modal title={candidate ? '编辑候选人资料' : '添加候选人'} subtitle={candidate ? '更新简历将保存新版本，历史分析仍保留原文快照。' : '导入资料后，可关联岗位并开始匹配。'} onClose={onClose} wide><form onSubmit={submit}><div className="modal-body">{!candidate && <div className="segmented" role="tablist" aria-label="简历导入方式"><button type="button" role="tab" aria-selected={tab === 'text'} className={tab === 'text' ? 'active' : ''} onClick={() => setTab('text')}><FileText size={16} />粘贴简历文本</button><button type="button" role="tab" aria-selected={tab === 'file'} className={tab === 'file' ? 'active' : ''} onClick={() => setTab('file')}><Upload size={16} />上传简历文件</button></div>}<div className="form-grid"><label>候选人姓名{tab === 'file' && <small>（可选，未填写时使用文件名）</small>}<input aria-label="候选人姓名" value={draft.name} onChange={event => setDraft({ ...draft, name: event.target.value })} required={tab === 'text'} maxLength={100} /></label>{tab === 'text' && <><label>简短介绍<input value={draft.headline} onChange={event => setDraft({ ...draft, headline: event.target.value })} placeholder="例如：TypeScript 开发 · AI 应用实践" maxLength={200} /></label><label>邮箱<input type="email" value={draft.email} onChange={event => setDraft({ ...draft, email: event.target.value })} maxLength={200} /></label><label>联系电话<input value={draft.phone} onChange={event => setDraft({ ...draft, phone: event.target.value })} maxLength={40} /></label></>}</div>{tab === 'text' ? <><label>技能标签<input value={draft.tags} onChange={event => setDraft({ ...draft, tags: event.target.value })} placeholder="使用逗号分隔，例如 TypeScript，安全测试" /></label><label>简历原文<textarea aria-label="简历原文" rows={12} value={draft.resumeText} onChange={event => setDraft({ ...draft, resumeText: event.target.value })} required minLength={50} maxLength={80000} placeholder="粘贴简历正文。请保留项目经历、个人承担的工作及成果，评价将引用这里的原文。" /></label></> : <><label className={`upload-area ${file ? 'has-file' : ''}`}><span className="upload-icon"><Upload size={28} /></span><strong>{file ? file.name : '选择一份简历文件'}</strong><span>{file ? `${(file.size / 1024).toFixed(0)} KB · 点击重新选择` : '支持 PDF、DOCX、TXT，单文件不超过 8 MB'}</span><input aria-label="简历文件" type="file" accept=".pdf,.docx,.txt" required onChange={event => { const selected = event.target.files?.[0] || null; setError(selected && selected.size > 8 * 1024 * 1024 ? '文件超过 8 MB，请缩小后重新选择。' : null); setFile(selected); }} /></label><div className="notice-banner blue compact"><FileText size={18} /><p>支持有文本层的 PDF、DOCX 与 TXT。扫描 PDF 需要先补充文本；本版不会将空文本继续评分。上传后可补充姓名、联系方式与标签。</p></div></>}<InlineError message={error} /></div><footer className="modal-footer"><span>请只使用已获授权的候选人资料</span><div><button type="button" className="button secondary" onClick={onClose}>取消</button><button className="button primary" disabled={busy || (tab === 'file' && !!file && file.size > 8 * 1024 * 1024)}>{busy ? tab === 'file' ? '正在上传与解析…' : '正在保存…' : candidate ? '保存资料' : tab === 'file' ? '上传并解析' : '保存候选人'}</button></div></footer></form></Modal>;
}

function LinkForm({ workspace, initial, onClose, onSaved }: { workspace: Workspace; initial: { jobId?: string; candidateId?: string }; onClose: () => void; onSaved: (application: Application) => Promise<void> }) {
  const [jobId, setJobId] = useState(initial.jobId || workspace.jobs[0]?.id || ''); const [candidateId, setCandidateId] = useState(initial.candidateId || workspace.candidates[0]?.id || ''); const [busy, setBusy] = useState(false); const [error, setError] = useState<string | null>(null);
  const exists = workspace.applications.some(application => application.jobId === jobId && application.candidateId === candidateId);
  async function submit(event: FormEvent) { event.preventDefault(); setBusy(true); setError(null); try { const application = await api<Application>('/api/applications', json('POST', { jobId, candidateId })); await onSaved(application); } catch (err) { setError(errorText(err)); } finally { setBusy(false); } }
  return <Modal title="关联候选人与岗位" subtitle="同一候选人可以关联不同岗位，分析和进展独立保存。" onClose={onClose}><form onSubmit={submit}><div className="modal-body stack-form"><label>选择候选人<select aria-label="选择候选人" value={candidateId} onChange={event => setCandidateId(event.target.value)} required><option value="" disabled>请选择候选人</option>{workspace.candidates.map(candidate => <option key={candidate.id} value={candidate.id}>{candidate.name}</option>)}</select></label><label>选择岗位<select aria-label="选择岗位" value={jobId} onChange={event => setJobId(event.target.value)} required><option value="" disabled>请选择岗位</option>{workspace.jobs.map(job => <option key={job.id} value={job.id}>{job.title} · {jobStatus[job.status]}</option>)}</select></label>{exists && <div className="notice-banner blue compact"><CheckCircle2 size={17} /><p>候选人已关联该岗位，可以直接进入评估。</p></div>}{(!workspace.jobs.length || !workspace.candidates.length) && <InlineError message="需要先创建至少一个岗位和一位候选人。" />}<InlineError message={error} /></div><footer className="modal-footer"><span /><div><button type="button" className="button secondary" onClick={onClose}>取消</button><button className="button primary" disabled={busy || !jobId || !candidateId || exists}>{busy ? '正在关联…' : '确认关联'}</button></div></footer></form></Modal>;
}

function InterviewForm({ workspace, initial, onClose, onSaved }: { workspace: Workspace; initial: { applicationId?: string; interview?: Interview }; onClose: () => void; onSaved: () => Promise<void> }) {
  const interview = initial.interview;
  function localInput(iso: string) { const date = new Date(iso); return new Date(date.getTime() - date.getTimezoneOffset() * 60000).toISOString().slice(0, 16); }
  const [applicationId, setApplicationId] = useState(interview?.applicationId || initial.applicationId || workspace.applications[0]?.id || '');
  const [scheduledAt, setScheduledAt] = useState(interview ? localInput(interview.scheduledAt) : localInput(new Date(Date.now() + 86400000).toISOString()));
  const [interviewer, setInterviewer] = useState(interview?.interviewer || '招聘负责人'); const [location, setLocation] = useState(interview?.location || ''); const [notes, setNotes] = useState(interview?.notes || ''); const [outcome, setOutcome] = useState<Interview['outcome']>(interview?.outcome || 'pending'); const [busy, setBusy] = useState(false); const [error, setError] = useState<string | null>(null);
  async function submit(event: FormEvent) { event.preventDefault(); setBusy(true); setError(null); try { await api(interview ? `/api/interviews/${interview.id}` : '/api/interviews', json(interview ? 'PUT' : 'POST', { ...(interview ? { notes, outcome } : { applicationId }), scheduledAt: new Date(scheduledAt).toISOString(), interviewer, location })); await onSaved(); } catch (err) { setError(errorText(err)); } finally { setBusy(false); } }
  return <Modal title={interview ? '面试安排与评价' : '安排面试'} subtitle="保存安排与记录，不会自动向候选人或面试官发送通知。" onClose={onClose}><form onSubmit={submit}><div className="modal-body stack-form"><label>候选人与岗位<select value={applicationId} onChange={event => setApplicationId(event.target.value)} disabled={!!interview} required aria-label="面试候选人与岗位">{workspace.applications.map(application => <option key={application.id} value={application.id}>{workspace.candidates.find(candidate => candidate.id === application.candidateId)?.name} · {workspace.jobs.find(job => job.id === application.jobId)?.title}</option>)}</select></label><div className="form-grid"><label>面试时间<input type="datetime-local" value={scheduledAt} onChange={event => setScheduledAt(event.target.value)} required /></label><label>面试官<input value={interviewer} onChange={event => setInterviewer(event.target.value)} required maxLength={100} /></label></div><label>地点或会议链接<input value={location} onChange={event => setLocation(event.target.value)} placeholder="填写线下地点或已有的会议链接" maxLength={500} required /></label>{interview && <><label>面试记录<textarea rows={7} aria-label="面试记录" value={notes} onChange={event => setNotes(event.target.value)} placeholder="记录候选人的回答、具体证据、亮点与待核实项。" maxLength={20000} /></label><label>面试结论<select aria-label="面试结论" value={outcome} onChange={event => setOutcome(event.target.value as Interview['outcome'])}>{Object.entries(outcomeLabels).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></label></>}<InlineError message={error} /></div><footer className="modal-footer"><span>按当前设备时区填写</span><div><button type="button" className="button secondary" onClick={onClose}>取消</button><button className="button primary" disabled={busy || !applicationId}>{busy ? '正在保存…' : '保存面试'}</button></div></footer></form></Modal>;
}
